  if(Arrays.asList("REVIEW","PAY","PAY_CODE").contains(action)){RefundMoneyScope.inspect(r(),c,b).requireAvailable(b.get("refund_fee"),false);require(!"SUCCESS".equals(text(b,"funds_state")),"平台已确认资金退款成功，不再执行审核付款");require("KEEP".equals(text(b,"goods_action"))||"DONE".equals(text(b,"goods_state")),"本退款取消、退回或实收尚未完成，不能执行付款审核");require(money(b.get("refund_fee")).equals(money(p.get("refund_fee"))),"平台最新金额与审核金额不同");require(r().db().queryForObject("SELECT COUNT(*) FROM oms_refund_operation WHERE company_code=? AND refund_id=? AND action='PAY' AND state IN ('PENDING','RUNNING','UNKNOWN','ACCEPTED','SUCCESS')",Long.class,c,b.get("id"))==0,"已有付款请求待确认，请先查询原结果");}
  if(Arrays.asList("PAY","PAY_CODE").contains(action))require(r().db().queryForObject("SELECT COUNT(*) FROM oms_refund_operation WHERE company_code=? AND refund_id=? AND action='REVIEW' AND state='SUCCESS' AND approved_hash=?",Long.class,c,b.get("id"),b.get("approved_hash"))>0,"请先完成平台退款审核，再执行付款");
  if("REFUSE_RETURN".equals(action))require("REFUND_AND_RETURN".equals(text(p,"dispute_type"))&&"WAIT_SELLER_AGREE".equals(text(p,"platform_status")),"平台当前不处于可拒绝退货申请的阶段");
  if("AGREE_RETURN".equals(action))require("REFUND_AND_RETURN".equals(text(p,"dispute_type"))&&"WAIT_SELLER_AGREE".equals(text(p,"platform_status")),"平台当前申请不处于可同意退货阶段");
